package com.example.data.curriculum

data class AdvancedSpeedMethod(
    val methodTitle: String,
    val mnemonicCode: String,
    val fiveSecondAlgorithm: String,
    val exampleShortcut: String
)

/**
 * موتور پیشرفته رمزنگاری حافظه (Mnemonics) و تکنیک‌های ابداعی حل سریع تست و نهایی
 * برای تک‌تک دروس و مباحث رشته علوم انسانی و دانشگاه فرهنگیان
 */
object AdvancedMnemonicEngine {

    fun getMethodForLesson(lesson: ZeroLesson): AdvancedSpeedMethod {
        val subj = lesson.normalizedSubjectId()
        val id = lesson.id

        // ۱. تکنیک‌های اختصاصی بر اساس شناسه دقیق درس
        when {
            // ======================== ریاضی و آمار ========================
            subj == "math" && id.contains("equations") -> return AdvancedSpeedMethod(
                methodTitle = "متد ابداعی «ترازوی ضرایب ۱ و −۱» (حل معادله درجه ۲ در ۳ ثانیه بدون دلتا)",
                mnemonicCode = "رمز «اول + وسط + آخر = صفر ⟹ جواب ۱ و c/a» | «وسط = اول + آخر ⟹ جواب −۱ و −c/a»",
                fiveSecondAlgorithm = "۱. در معادله ax² + bx + c = 0 قبل از هر کاری ضرایب را با هم جمع کن.\n" +
                    "۲. اگر a + b + c = 0 شد: ریشه اول x = 1 و ریشه دوم x = c/a است.\n" +
                    "۳. اگر ضریب وسط برابر جمع دو طرف بود (b = a + c): ریشه اول x = -1 و ریشه دوم x = -c/a است.\n" +
                    "۴. برای بیشینه و کمینه سهمی فقط فرمول طول رأس x = -b / 2a را بزن و عدد را در معادله بگذار.",
                exampleShortcut = "در معادله 5x² - 13x + 8 = 0 چون 5 + (-13) + 8 = 0 است، بدون دلتا در ۲ ثانیه: x₁ = 1 و x₂ = 8/5!"
            )
            subj == "math" && (id.contains("radicals_powers") || id.contains("powers")) -> return AdvancedSpeedMethod(
                methodTitle = "متد ابداعی «داخل بر خارج» در رادیکال و «جایگذاری عدد ۱ و ۲» در اتحادها",
                mnemonicCode = "رمز توان کسری: «توانِ داخلِ رادیکال در صورت، فرجهٔ بیرون در مخرج: ⁿ√(aᵐ) = a^(m/n)»",
                fiveSecondAlgorithm = "۱. اگر تست ساده‌سازی عبارت جبری یا اتحاد با متغیرهای x و y بود، به جای x عدد 2 و به جای y عدد 1 بگذار.\n" +
                    "۲. عدد حاصل از صورت سوال را حساب کن و همان عدد 2 و 1 را در ۴ گزینه بگذار؛ گزینه‌ای که همان عدد را بدهد ۱۰۰٪ جواب است!\n" +
                    "۳. در مخرج رادیکالی از شکل (√a - √b)، فوراً صورت را در مزدوج یعنی (√a + √b) ضرب کن و مخرج را (a - b) بنویس.",
                exampleShortcut = "برای ۱ / (√5 - √3): مخرج می‌شود 5 - 3 = 2 و صورت می‌شود √5 + √3، یعنی (√5 + √3) / 2 در ۳ ثانیه!"
            )
            subj == "math" && id.contains("functions") -> return AdvancedSpeedMethod(
                methodTitle = "متد ابداعی «قانون خط قرمز دامنه» و «حرکت راست‌به‌چپ در ترکیب توابع (fog)»",
                mnemonicCode = "رمز دامنه: «مخرج ≠ 0 (ریشه مخرج را بنداز دور) | زیر رادیکال زوج ≥ 0» | رمز fog: «اول ماشین راست (g)، بعد ماشین چپ (f)»",
                fiveSecondAlgorithm = "۱. تشخیص تابع در زوج‌های مرتب: فقط عددهای اول (سمت چپ پرانتزها) را نگاه کن؛ اگر عددی دو بار با خروجی متفاوت تکرار شد، تابع نیست!\n" +
                    "۲. در نمودار: خط عمودی بکش؛ اگر نمودار را در ۲ نقطه قطع کرد، تابع نیست.\n" +
                    "۳. در تابع نمایی y = A(1 ± r)^t: کلمه «رشد/تورم» یعنی (1 + r) و کلمه «استهلاک/کاهش» یعنی (1 - r).",
                exampleShortcut = "در (f o g)(2) هرگز فرمول کلی fog را ننویس! فقط عدد 2 را بده به g، جوابش را بده به f و تمام!"
            )
            subj == "math" && id.contains("sequences") -> return AdvancedSpeedMethod(
                methodTitle = "متد ابداعی «فرمول آسانسور پرش» و «قانون جمله وسط» در دنباله‌ها",
                mnemonicCode = "رمز پرش حسابی: «d = تفاضل دو جمله ÷ تفاضل شماره‌ها» | رمز واسطه: «حسابی: ۲ برابر وسطی = جمع چپ و راست | هندسی: مربع وسطی = ضرب چپ و راست»",
                fiveSecondAlgorithm = "۱. وقتی دو جمله از دنباله حسابی داری (مثلاً جمله ۴ و جمله ۱۰)، هرگز دستگاه معادله ننویس!\n" +
                    "۲. کم کردن دو عدد را تقسیم بر کم کردن شماره‌هایشان کن تا قدر نسبت d پیدا شود: d = (a₁₀ - a₄) / (10 - 4).\n" +
                    "۳. از همان جمله معلوم به اندازه اختلاف شماره‌ها بپر جلو: a₂₀ = a₁₀ + 10d.",
                exampleShortcut = "اگر x-1 و x+3 و 3x-1 دنباله حسابی باشند: ۲ برابر وسطی = جمع دو طرف ⟹ 2(x+3) = (x-1) + (3x-1) ⟹ x = 4!"
            )
            subj == "math" && (id.contains("statistics") || id.contains("regression")) -> return AdvancedSpeedMethod(
                methodTitle = "متد ابداعی «فیلتر جمع و تفریق در پراکندگی» و «نصفِ عدد وسط برای خط فقر»",
                mnemonicCode = "رمز واریانس و انحراف معیار: «جمع و تفریق بی‌اثر (خط بزن!) | ضرب در k: انحراف معیار × |k| و واریانس × k²»",
                fiveSecondAlgorithm = "۱. اگر گفت داده‌ها را در a ضرب و با b جمع کردیم، عدد b را برای واریانس و انحراف معیار کاملاً خط بزن!\n" +
                    "۲. انحراف معیار جدید = |a| × انحراف معیار قدیم | واریانس جدید = a² × واریانس قدیم.\n" +
                    "۳. برای خط فقر به روش میانه: داده‌ها را از کوچک به بزرگ بچین، عدد دقیقاً وسط را نصف کن!",
                exampleShortcut = "انحراف معیار = 3، داده‌ها در -2 ضرب و با 19 جمع شدند ⟹ 19 را خط بزن! انحراف معیار جدید = 3 × |-2| = 6 و واریانس = 36!"
            )
            subj == "math" && (id.contains("combinatorics") || id.contains("probability")) -> return AdvancedSpeedMethod(
                methodTitle = "متد ابداعی «کسر پله‌ای ترکیب» و «تنگ کردن مخرج در احتمال شرطی»",
                mnemonicCode = "رمز احتمال شرطی P(A|B): «عبارت بعد از کلمه (به شرط آنکه / اگر بدانیم) کل فضای نمونه جدید و مخرج کسر است!»",
                fiveSecondAlgorithm = "۱. برای محاسبه سریع ترکیب C(n,r) بدون فاکتوریل: در صورت کسر به تعداد عدد پایین (r)، عدد بالا (n) را یکی‌یکی کم کن و در هم ضرب کن؛ در مخرج هم فاکتوریل عدد پایین را بنویس.\n" +
                    "۲. در احتمال شرطی، اصلاً فرمول ننویس! کل حالت‌های جهان را فراموش کن و فقط حالت‌های جملهٔ «اگر بدانیم...» را بشمار و در مخرج بگذار!",
                exampleShortcut = "محاسبه C(8,3) در ۳ ثانیه: صورت ۳ تا عدد از ۸ رو به پایین (8 × 7 × 6) تقسیم بر مخرج (3 × 2 × 1 = 6) ⟹ 6 با 6 می‌رود = 56!"
            )
            subj == "math" -> return AdvancedSpeedMethod(
                methodTitle = "متد ابداعی «قول و قرار در گزاره شرطی» و «عددگذاری هوشمند در ریاضی انسانی»",
                mnemonicCode = "رمز شرطی (p ⟹ q): «فقط T ⟹ F (بدقولی) نادرست است!» | رمز هم‌ارزی: «p ⟹ q هم‌ارز است با ~p ∨ q (نقیض اولی یا دومی)»",
                fiveSecondAlgorithm = "۱. گزاره شرطی فقط وقتی F (نادرست) است که سمت چپ درست (T) و سمت راست نادرست (F) باشد.\n" +
                    "۲. اگر مقدم نادرست (F) باشد، بدون خواندن بقیه سوال فوراً بگو کل گزاره شرطی درست (T) است!\n" +
                    "۳. نقیضِ گزاره شرطی ~(p ⟹ q) همیشه می‌شود: p ∧ ~q (مقدم درست و تالی نادرست).",
                exampleShortcut = "در «اگر 2+2=5 باشد آنگاه فیل پرواز می‌کند»، چون مقدم غلط است (F)، کل جمله شرطی ۱۰۰٪ درست (T) است!"
            )

            // ======================== علوم و فنون ادبی و عروض ========================
            lesson.isAroozLesson() -> return AdvancedSpeedMethod(
                methodTitle = "متد ابداعی «کد ۴ هجای اول مصراع» (تشخیص وزن و بحر در ۵ ثانیه بدون خواندن آوازی)",
                mnemonicCode = "رمز ۴ هجای اول:\n" +
                    "• [ U — — — ]  مفاعیلن (بحر هزج)\n" +
                    "• [ — U — — ]  فاعلاتن (بحر رمل)\n" +
                    "• [ — — U — ]  مستفعلن (بحر رجز)\n" +
                    "• [ U — — U ]  فعولن فعولن (بحر متقارب) یا مفاعلاتن\n" +
                    "• [ — U U — ]  مفتعلن (وزن دوری)",
                fiveSecondAlgorithm = "۱. به جای تقطیع کل بیت، فقط ۴ هجای اول مصراع را به خط عروضی بنویس (حرف ۱ یا ۲ حرفی = U کوتاه | حرف ۳ حرفی یا دارای آ/او/ای = — بلند | کشیده مثل دست/یار = — U).\n" +
                    "۲. الگوی ۴ هجای اول را با ۵ کد بالا مطابقت بده تا ۳ گزینه فوراً حذف شود!\n" +
                    "۳. اگر در وسط مصراع مکث طبیعی و تقارن دیدی، گزینهٔ «وزن دوری» را انتخاب کن.",
                exampleShortcut = "مصراع «ای ساربان آهسته ران»: اِی (—) + سا (—) + رِ (U) + بان (— U) ⟹ چهار هجای اول [ — — U — ] = مستفعلن (بحر رجز) در ۴ ثانیه!"
            )
            subj == "fonoon" && (id.contains("history") || id.contains("styles")) -> return AdvancedSpeedMethod(
                methodTitle = "متد ابداعی «رمز جمله‌ای قرن‌ها و شاعران» + «رادار ۳ ثانیه‌ای سبک‌شناسی»",
                mnemonicCode = "رمز سبک‌ها:\n" +
                    "• خراسانی (قرن ۴ و ۵): کلمات کهن (همی، اندر، ایدون) + قصیده و شاهنامه + تشبیه حسی.\n" +
                    "• بینابینی (قرن ۶): علوم نجوم و طب + ورود عرفان (سنایی، عطار، نظامی، خاقانی) + نثر فنی (کلیله و دمنه).\n" +
                    "• عراقی (قرن ۷ تا ۹): غزل عاشقانه و عارفانه (سعدی، مولوی، حافظ) + ایهام.\n" +
                    "• هندی (قرن ۱۰ و ۱۱): تک‌بیت و اسلوب معادله + حس‌آمیزی و پارادوکس + واژگان کوچه و بازار (صائب، بیدل، کلیم).\n" +
                    "• مشروطه (قرن ۱۳ و ۱۴): وطن، قانون، آزادی، روزنامه (بهار، عارف، عشقی، فرخی یزدی).",
                fiveSecondAlgorithm = "۱. در تست‌های تعیین سبک بیت: اول نگاه کن آیا بین دو مصراع می‌توان «همان‌طور که» گذاشت؟ اگر بله = اسلوب معادله و سبک هندی!\n" +
                    "۲. اگر کلمات «همی، ایدون، مر، به...اندر» داشت = سبک خراسانی.\n" +
                    "۳. اگر واژگان «قانون، وطن، استبداد، مجلس» داشت = دوره مشروطه.",
                exampleShortcut = "رمز آثار منثور قرن ۶: «کلیله در چهارمقالهٔ حمیدی به تذکرةالاولیا رسید» (کلیله و دمنه، چهارمقاله، مقامات حمیدی، تذکرةالاولیا)!"
            )
            subj == "fonoon" -> return AdvancedSpeedMethod(
                methodTitle = "متد ابداعی «فرمول تفکیک آرایه‌های دوقلو» (تشبیه بلیغ از استعاره مکنیه / ایهام از ایهام تناسب)",
                mnemonicCode = "رمز اضافه تشبیهی در برابر استعاری: «بین دو کلمه (مانندِ) بگذار و برعکس بخوان: اگر معنی داد = تشبیه بلیغ | اگر یکی از اجزای انسان/درخت بود = استعاره مکنیه!»",
                fiveSecondAlgorithm = "۱. تفکیک اضافه تشبیهی و استعاری: «چراغِ دانش» ⟹ دانش مانندِ چراغ است (معنی داد = تشبیه بلیغ). «دستِ روزگار» ⟹ روزگار مانندِ دست است؟ خیر! دست عضو انسان است = استعاره مکنیه (تشخیص).\n" +
                    "۲. تفکیک ایهام و ایهام تناسب: اگر هر ۲ معنی کلمه در بیت درست باشد = ایهام؛ اگر فقط ۱ معنی در بیت بیاید و معنی دوم فقط با کلمه دیگری در بیت مراعات نظیر بسازد = ایهام تناسب!\n" +
                    "۳. تفکیک اسلوب معادله و تمثیل: اگر دو مصراع کاملاً مستقل باشند و جایشان عوض شود = اسلوب معادله؛ اگر با «که / زیرا / چو» به هم وصل باشند = تمثیل.",
                exampleShortcut = "در «چون شمع سحرگه به سرِ دار بسوختم»، واژه «دار» ۱) چوب اعدام (معنی اصلی بیت) ۲) درخت (تناسب با شمع/برگ)!"
            )

            // ======================== عربی اختصاصی انسانی ========================
            subj == "arabic" -> return AdvancedSpeedMethod(
                methodTitle = "متد ابداعی «اسکنر ۳ نقطه‌ای عربی» (تشخیص صیغه، باب، حال، تمییز و استثنا در ۵ ثانیه)",
                mnemonicCode = "رمز ۸ باب مزید: «إفعال، تفعیل، مفاعله، تفعّل، تفاعل، افتعال، انفعال (مجهول/لازم)، استفعال»\n" +
                    "رمز منصوبات دوازدهم: «حال = چطور؟ (نکره منصوب یا جمله بعد از اسم ال‌دار) | تمییز = از چه نظر؟ (بعد از عدد، وزن و أفعل تفضیل) | مفعول مطلق = مصدر هم‌ریشه با فعل»",
                fiveSecondAlgorithm = "۱. در تست‌های ترجمه کنکور: هرگز کل جمله را ترجمه نکن! فقط به «فعل» و «ضمیر و الف و لام (ال)» نگاه کن:\n" +
                    "   • قد + ماضی = ماضی نقلی (انجام داده است) | کان + ماضی = ماضی بعید (انجام داده بود) | کان + مضارع = ماضی استمراری (انجام می‌داد).\n" +
                    "   • اسم نکره (تنوین‌دار) + فعل بعد از آن = صفت (با «که» ترجمه می‌شود و فعل مضارع بعد از کان + اسم + خبر، ماضی استمراری یا مضارع التزامی می‌شود).\n" +
                    "۲. در لای نفی جنس: «لا + اسم نکره با فتحه بدون تنوین» همیشه «هیچ ... نیست» ترجمه می‌شود.",
                exampleShortcut = "دیدن «أکرَمَ» (بر وزن أفعلَ) در اول و وسط: مضارعش همیشه با ضمه «یُـ» شروع می‌شود (یُکرِمُ)!"
            )

            // ======================== زبان انگلیسی ========================
            subj == "english" -> return AdvancedSpeedMethod(
                methodTitle = "متد ابداعی «رادار ۲ کلمه قبل و بعد از جای خالی» (حل تست گرامر بدون ترجمه جمله)",
                mnemonicCode = "رمز زمان‌ها و گرامر Vision 1-3:\n" +
                    "• since / for ⟹ have/has + P.P.\n" +
                    "• before + V2 (گذشته) ⟹ had + P.P. (ماضی بعید)\n" +
                    "• by + اسم (توسطِ...) ⟹ مجهول (be + P.P.)\n" +
                    "• If + گذشته ساده (V2 / were) ⟹ شرطی نوع ۲ (would + فعل ساده)\n" +
                    "• بعد از حروف اضافه (of, in, on, for, without, by) و (enjoy, mind, avoid, suggest) ⟹ فعل + ing",
                fiveSecondAlgorithm = "۱. در تست‌های Tag Question (دنباله سوالی آخر جمله): به فعل جمله اول نگاه کن؛ اگر مثبت است، دنباله را منفی کن و اگر منفی است مثبت کن (تله کنکور: جملاتی که never, hardly, seldom, rarely, little دارند منفی محسوب می‌شوند و تگ آن‌ها باید مثبت باشد!).\n" +
                    "۲. در ضمایر موصولی (who, whom, which, where): قبل از جای خالی انسان + بعد از جای خالی فعل = who | انسان + فاعل و فعل = whom | غیرانسان = which.",
                exampleShortcut = "جمله «Ali rarely goes to cinema, ____?» ⟹ چون rarely منفی است، تگ باید مثبت باشد: does he!"
            )

            // ======================== فلسفه و منطق ========================
            lesson.isLogicLesson() -> return AdvancedSpeedMethod(
                methodTitle = "متد ابداعی «کد چهارگوشه مربع تقابل» و «شگرد خط زدن حد وسط در قیاس»",
                mnemonicCode = "رمز کلیات خمس: «چیستی کامل = نوع | بخش مشترک = جنس | مرز جداکننده = فصل | ویژگی لازم/اتفاقی = عرض خاص و عام»\n" +
                    "رمز عکس مستوی: «موجبه کلی (الف) و موجبه جزئی (ج) هر دو عکسشان می‌شود موجبه جزئی (ج)! سالبه کلی (ب) خودش می‌ماند (ب)؛ سالبه جزئی (د) اصلاً عکس ندارد!»",
                fiveSecondAlgorithm = "۱. در مربع تقابل: قوی‌ترین رابطه «تناقض» (ضربدری: الف با د، ب با ج) است که هرگز با هم صدق و کذب نمی‌شوند.\n" +
                    "۲. در شکل‌های چهارگانه قیاس اقترانی: جای «حد وسط (م)» را در مقدمه اول و دوم پیدا کن:\n" +
                    "   • شکل اول: م موضوع در اول، محمول در دوم (م - الف / ب - م).\n" +
                    "   • شکل دوم: م در هر دو محمول (آخر جمله) است (همیشه یک مقدمه سالبه دارد و نتیجه‌اش همیشه سالبه است!).\n" +
                    "   • شکل سوم: م در هر دو موضوع (اول جمله) است (نتیجه‌اش همیشه جزئی است!).\n" +
