                mnemonicCode = "رمز فرمول BMI: «وزن (کیلوگرم) ÷ مجذور قد (متر به توان ۲)» | «زیر ۱۸.۵ کمبود وزن | ۱۸.۵ تا ۲۴.۹ طبیعی | ۲۵ تا ۲۹.۹ اضافه وزن | بالای ۳۰ چاقی»",
                fiveSecondAlgorithm = "۱. پیشگیری سطح اول: قبل از بروز بیماری (واکسیناسیون، تغذیه سالم، ورزش).\n" +
                    "۲. پیشگیری سطح دوم: غربالگری و تشخیص زودهنگام بیماری (آزمایش قند و فشار خون).\n" +
                    "۳. پیشگیری سطح سوم: بازتوانی و جلوگیری از عوارض و معلولیت پس از بیماری.",
                exampleShortcut = "فردی با وزن ۷۲ کیلوگرم و قد ۲ متر: BMI = 72 ÷ (2 × 2) = 72 ÷ 4 = 18!"
            )
            subj == "media_environment" -> return AdvancedSpeedMethod(
                methodTitle = "متد ابداعی «شکار فنون اقناع در سواد رسانه‌ای و شاخص‌های محیط زیست»",
                mnemonicCode = "رمز فنون اقناع رسانه: «شهادت = استفاده از سلبریتی/متخصص | همنوایی = همه می‌خرند پس تو هم بخر | کلی‌گویی درخشان = شعارهای مبهم و هیجانی | انتقال = پیوند با نمادهای مقدس/ملی»",
                fiveSecondAlgorithm = "۱. در سواد رسانه‌ای: «دروازه‌بانی خبر» یعنی گزینش، حذف یا برجسته‌سازی بخشی از واقعیت توسط رسانه.\n" +
                    "۲. در انسان و محیط زیست: «آب مجازی» یعنی کل آب پنهان مصرف‌شده در تمام مراحل تولید یک کالا (مثلاً ۱۵ هزار لیتر آب برای ۱ کیلو گوشت).\n" +
                    "۳. در مدیریت خانواده: ارتباط مؤثر بر پایه «گوش دادن فعال و همدلی» است.",
                exampleShortcut = "تبلیغ یک کالا با تصویر یک فوتبالیست مشهور = تکنیک اقناعی «شهادت (گواهی)» در ۲ ثانیه!"
            )
            subj == "study_methods" -> return AdvancedSpeedMethod(
                methodTitle = "متد ابداعی «تکنیک دو خودکار در مدیریت جلسه کنکور و مرور فاصله‌دار»",
                mnemonicCode = "رمز ضربدر و منها در سر جلسه: «سوال ساده = حل فوری | سوال وقت‌گیر و بلد = علامت ضربدر (×) برای دور دوم | سوال شک‌دار و سخت = علامت منها (−) برای رها کردن»",
                fiveSecondAlgorithm = "۱. قانون نمره منفی: هر ۳ تست غلط، ۱ تست درست را کامل از بین می‌برد؛ پس هرگز بین ۳ یا ۴ گزینه شانسی نزن!\n" +
                    "۲. چرخه طلایی مرور ضد فراموشی (منحنی ابینگهاوس): مرور اول ۲۴ ساعت بعد، مرور دوم ۱ هفته بعد، مرور سوم ۱ ماه بعد.\n" +
                    "۳. تکنیک فاینمن: هر مبحثی را طوری برای یک دانش‌آموز پایه ششم توضیح بده که بدون اصطلاحات پیچیده متوجه شود.",
                exampleShortcut = "در دفترچه کنکور، اگر در ۳۰ ثانیه اول راه حل تست به ذهنت نرسید، فوراً کنارش × بگذار و برو تست بعدی!"
            )
            else -> return AdvancedSpeedMethod(
                methodTitle = "متد ابداعی «الگوی ۳ ستونی فرهنگیان و مهارت معلمی» (قرائتی، سند تحول و هوش معلمی)",
                mnemonicCode = "رمز ۶ ساحت سند تحول بنیادین: «اعتقادی-عبادی-اخلاقی (محوری‌ترین) | اجتماعی-سیاسی | زیستی-بدنی | زیباشناختی-هنری | اقتصادی-حرفه‌ای | علمی-فناورانه»",
                fiveSecondAlgorithm = "۱. در تست‌های مهارت معلمی استاد قرائتی: هر جا سخن از «تکبر علمی، تحقیر شاگرد، تبعیض یا سخن گفتن بالاتر از درک مخاطب» بود = آفت معلمی!\n" +
                    "۲. مراحل تدریس استاد قرائتی (قـحـب): قبل از تدریس (اخلاص، فیش‌برداری، طرح درس)، حین تدریس (تمثیل، پرسش، تشویق)، بعد از تدریس (ارزشیابی و عمل معلم).\n" +
                    "۳. در هوش و استعداد معلمی: اولین اقدام در برابر افت تحصیلی یا خطای دانش‌آموز همیشه «گفت‌وگوی خصوصی و همدلانه برای ریشه‌یابی» است.",
                exampleShortcut = "تست فرهنگیان: «فیش‌برداری و شناخت مخاطب» مربوط به کدام مرحله است؟ ⟵ قبل از تدریس!"
            )
        }
    }
